        """Lock file permissions so they cannot be modified or deleted"""
        for f, s in os.walk(self.scopes):
            f.stat().st_mode = f.st_mode.replace(0, 0)
        for f, s in os.walk(self.scopes):
            s.st_mode = f.st_mode.replace(0, 0)

